// Cloud-ready Spring Boot REST API
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderRepository repository;

    public OrderController(OrderRepository repository) {
        this.repository = repository;
    }

    @GetMapping
    public List<Order> getAllOrders() {
        return repository.findAll(); // RDS manages the database
    }

    @PostMapping
    public Order createOrder(@RequestBody OrderRequest request) {
        var order = new Order(null, request.item(), request.quantity());
        return repository.save(order); // Stateless: any instance can handle this
    }
}

record Order(Long id, String item, int quantity) {}
record OrderRequest(String item, int quantity) {}

// Health check endpoint that load balancer probes
@RestController
public class HealthController {
    private final DataSource dataSource;

    public HealthController(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    @GetMapping("/health")
    public ResponseEntity<Map<String, String>> health() {
        try {
            // Verify database connectivity
            dataSource.getConnection().close();
            return ResponseEntity.ok(
                Map.of("status", "healthy", "database", "connected")
            );
        } catch (Exception e) {
            // Load balancer sees 503 and stops routing traffic here
            return ResponseEntity.status(503)
                .body(Map.of("status", "unhealthy", "error", e.getMessage()));
        }
    }
}

// Spring Boot service using RDS, S3, and SQS
@Service
public class OrderService {
    private final OrderRepository repository; // RDS via JPA
    private final S3Client s3Client;
    private final SqsClient sqsClient;

    public Order createOrder(OrderRequest request) {
        var order = repository.save(
            new Order(null, request.item(), request.quantity())
        ); // Saved to RDS PostgreSQL

        // Upload order receipt PDF to S3
        s3Client.putObject(
            PutObjectRequest.builder()
                .bucket("order-receipts")
                .key("receipt-" + order.id() + ".pdf")
                .build(),
            RequestBody.fromBytes(generatePdf(order))
        );

        // Send message to SQS for async email notification
        sqsClient.sendMessage(
            SendMessageRequest.builder()
                .queueUrl("https://sqs.us-east-1.amazonaws.com/123456/notifications")
                .messageBody("{\"orderId\":" + order.id() + "}")
                .build()
        );
        return order;
    }
}

// Define RDS database and ECS cluster for Spring Boot app
resource "aws_db_instance" "orders_db" {
  identifier        = "orders-database"
  engine            = "postgres"
  engine_version    = "15.3"
  instance_class    = "db.t3.micro"
  allocated_storage = 20
  username          = "admin"
  password          = var.db_password // From environment variable
}

resource "aws_ecs_cluster" "app_cluster" {
  name = "spring-boot-cluster"
}

resource "aws_ecs_task_definition" "app" {
  family                   = "order-service"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  container_definitions    = jsonencode([{
    name  = "order-service"
    image = "123456.dkr.ecr.us-east-1.amazonaws.com/order-service:latest"
    environment = [
      {name = "DB_HOST", value = aws_db_instance.orders_db.endpoint}
    ]
  }])
}
